const eventCategories = {
  mouse: ["click", "mouseover", "mousedown"],
  keyboard: ["keydown", "keyup"],
  form: ["submit", "change", "input"]
};

console.log(eventCategories.mouse); // [ 'click', 'mouseover', 'mousedown' ]

const listeners = [];

function addListener(fn) {
  listeners.push(fn);
}

function fireEvent(value) {
  listeners.forEach((fn) => fn(value));
}

addListener((v) => console.log("first handler:", v));
addListener((v) => console.log("second handler:", v));
fireEvent("clicked");
// "first handler:" "clicked"
// "second handler:" "clicked"

function simulateBubble(path, handlers) {
  for (const el of path) {
    if (handlers[el]) handlers[el](el);
  }
}

simulateBubble(["button", "div", "body"], {
  button: (el) => console.log("handler on", el),
  div: (el) => console.log("handler on", el)
});
// "handler on" "button"
// "handler on" "div"
